"use strict";(globalThis.webpackChunkdocs=globalThis.webpackChunkdocs||[]).push([[1800],{4553:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/langgraph/docs/intro","label":"LangGraph \uc18c\uac1c","docId":"intro","unlisted":false},{"type":"category","label":"\uae30\ubcf8 \uac1c\ub150","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/langgraph/docs/basics/state","label":"State (\uc0c1\ud0dc \uad00\ub9ac)","docId":"basics/state","unlisted":false},{"type":"link","href":"/langgraph/docs/basics/nodes","label":"Node (\ub178\ub4dc)","docId":"basics/nodes","unlisted":false},{"type":"link","href":"/langgraph/docs/basics/edges","label":"Edge (\uc5e3\uc9c0)","docId":"basics/edges","unlisted":false},{"type":"link","href":"/langgraph/docs/basics/graph","label":"Graph (\uadf8\ub798\ud504)","docId":"basics/graph","unlisted":false}],"href":"/langgraph/docs/category/\uae30\ubcf8-\uac1c\ub150"},{"type":"category","label":"\uace0\uae09 \uae30\ub2a5","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/langgraph/docs/advanced/checkpointing","label":"Checkpointing (\uccb4\ud06c\ud3ec\uc778\ud305)","docId":"advanced/checkpointing","unlisted":false},{"type":"link","href":"/langgraph/docs/advanced/streaming","label":"Streaming (\uc2a4\ud2b8\ub9ac\ubc0d)","docId":"advanced/streaming","unlisted":false},{"type":"link","href":"/langgraph/docs/advanced/human-in-the-loop","label":"Human-in-the-Loop (HITL)","docId":"advanced/human-in-the-loop","unlisted":false}],"href":"/langgraph/docs/category/\uace0\uae09-\uae30\ub2a5"},{"type":"category","label":"\uc2e4\uc804 \uc608\uc81c","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/langgraph/docs/examples/simple-chatbot","label":"\uac04\ub2e8\ud55c \ucc57\ubd07 \ub9cc\ub4e4\uae30","docId":"examples/simple-chatbot","unlisted":false},{"type":"link","href":"/langgraph/docs/examples/agent-with-tools","label":"\ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\ub294 \uc5d0\uc774\uc804\ud2b8","docId":"examples/agent-with-tools","unlisted":false},{"type":"link","href":"/langgraph/docs/examples/multi-agent","label":"\uba40\ud2f0 \uc5d0\uc774\uc804\ud2b8 \uc2dc\uc2a4\ud15c","docId":"examples/multi-agent","unlisted":false}],"href":"/langgraph/docs/category/\uc2e4\uc804-\uc608\uc81c"}]},"docs":{"advanced/checkpointing":{"id":"advanced/checkpointing","title":"Checkpointing (\uccb4\ud06c\ud3ec\uc778\ud305)","description":"\uccb4\ud06c\ud3ec\uc778\ud305\uc740 \uadf8\ub798\ud504 \uc2e4\ud589 \uc0c1\ud0dc\ub97c \uc800\uc7a5\ud558\uace0 \ubcf5\uc6d0\ud558\ub294 \uae30\ub2a5\uc785\ub2c8\ub2e4. \ub300\ud654 \uae30\ub85d \uc720\uc9c0, \uc2e4\ud589 \uc7ac\uac1c, \ud0c0\uc784 \ud2b8\ub798\ube14 \ub4f1\uc744 \uac00\ub2a5\ud558\uac8c \ud569\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"advanced/human-in-the-loop":{"id":"advanced/human-in-the-loop","title":"Human-in-the-Loop (HITL)","description":"Human-in-the-Loop\uc740 \uadf8\ub798\ud504 \uc2e4\ud589 \uc911 \uc0ac\ub78c\uc758 \uac1c\uc785\uc744 \uac00\ub2a5\ud558\uac8c \ud569\ub2c8\ub2e4. \uc2b9\uc778, \uc218\uc815, \ud53c\ub4dc\ubc31 \ub4f1 \uc0ac\ub78c\uc758 \ud310\ub2e8\uc774 \ud544\uc694\ud55c \uc6cc\ud06c\ud50c\ub85c\uc6b0\uc5d0 \ud544\uc218\uc801\uc785\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"advanced/streaming":{"id":"advanced/streaming","title":"Streaming (\uc2a4\ud2b8\ub9ac\ubc0d)","description":"\uc2a4\ud2b8\ub9ac\ubc0d\uc744 \ud1b5\ud574 \uadf8\ub798\ud504 \uc2e4\ud589 \uacfc\uc815\uc744 \uc2e4\uc2dc\uac04\uc73c\ub85c \uad00\ucc30\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. LLM \ud1a0\ud070 \uc2a4\ud2b8\ub9ac\ubc0d, \ub178\ub4dc\ubcc4 \uc9c4\ud589 \uc0c1\ud669, \ub514\ubc84\uae45 \uc815\ubcf4 \ub4f1\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"basics/edges":{"id":"basics/edges","title":"Edge (\uc5e3\uc9c0)","description":"Edge\ub294 \ub178\ub4dc \uac04\uc758 \uc5f0\uacb0\uacfc \uc2e4\ud589 \ud750\ub984\uc744 \uc815\uc758\ud569\ub2c8\ub2e4. \ub2e8\uc21c \uc5f0\uacb0\ubd80\ud130 \uc870\uac74\ubd80 \ubd84\uae30\uae4c\uc9c0 \ub2e4\uc591\ud55c \ud328\ud134\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"basics/graph":{"id":"basics/graph","title":"Graph (\uadf8\ub798\ud504)","description":"Graph\ub294 Node\uc640 Edge\ub97c \uc870\ud569\ud558\uc5ec \uc804\uccb4 \uc6cc\ud06c\ud50c\ub85c\uc6b0\ub97c \uad6c\uc131\ud558\ub294 \ucee8\ud14c\uc774\ub108\uc785\ub2c8\ub2e4. \uadf8\ub798\ud504 \ube4c\ub4dc, \ucef4\ud30c\uc77c, \uc2e4\ud589\uc758 \uc804\uccb4 \uacfc\uc815\uc744 \ub2e4\ub8f9\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"basics/nodes":{"id":"basics/nodes","title":"Node (\ub178\ub4dc)","description":"Node\ub294 \uadf8\ub798\ud504\uc5d0\uc11c \uc2e4\uc81c \uc791\uc5c5\uc744 \uc218\ud589\ud558\ub294 \ub2e8\uc704\uc785\ub2c8\ub2e4. \uac01 \ub178\ub4dc\ub294 State\ub97c \uc785\ub825\ubc1b\uc544 \ucc98\ub9ac\ud558\uace0, \uc5c5\ub370\uc774\ud2b8\ub41c State\ub97c \ubc18\ud658\ud569\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"basics/state":{"id":"basics/state","title":"State (\uc0c1\ud0dc \uad00\ub9ac)","description":"State\ub294 LangGraph\uc758 \ud575\uc2ec \uac1c\ub150\uc73c\ub85c, \uadf8\ub798\ud504\uc758 \ubaa8\ub4e0 \ub178\ub4dc\uac00 \uacf5\uc720\ud558\ub294 \ub370\uc774\ud130 \uad6c\uc870\uc785\ub2c8\ub2e4. \uac01 \ub178\ub4dc\ub294 State\ub97c \uc785\ub825\ubc1b\uc544 \ucc98\ub9ac\ud558\uace0, \uc218\uc815\ub41c State\ub97c \ubc18\ud658\ud569\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"examples/agent-with-tools":{"id":"examples/agent-with-tools","title":"\ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\ub294 \uc5d0\uc774\uc804\ud2b8","description":"LangGraph\ub85c \uc678\ubd80 \ub3c4\uad6c\ub97c \ud638\ucd9c\ud560 \uc218 \uc788\ub294 ReAct \uc5d0\uc774\uc804\ud2b8\ub97c \ub9cc\ub4e4\uc5b4\ubd05\ub2c8\ub2e4. \uc774 \ud328\ud134\uc740 LLM\uc774 \ud544\uc694\uc5d0 \ub530\ub77c \ub3c4\uad6c\ub97c \uc120\ud0dd\ud558\uace0 \ud638\ucd9c\ud558\ub294 \uac00\uc7a5 \uc77c\ubc18\uc801\uc778 \uc5d0\uc774\uc804\ud2b8 \uad6c\uc870\uc785\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"examples/multi-agent":{"id":"examples/multi-agent","title":"\uba40\ud2f0 \uc5d0\uc774\uc804\ud2b8 \uc2dc\uc2a4\ud15c","description":"\uc5ec\ub7ec \uc804\ubb38 \uc5d0\uc774\uc804\ud2b8\uac00 \ud611\uc5c5\ud558\uc5ec \ubcf5\uc7a1\ud55c \uc791\uc5c5\uc744 \uc218\ud589\ud558\ub294 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4e4\uc5b4\ubd05\ub2c8\ub2e4. \uac01 \uc5d0\uc774\uc804\ud2b8\ub294 \ud2b9\uc815 \uc5ed\ud560\uc5d0 \uc9d1\uc911\ud558\uace0, \uc288\ud37c\ubc14\uc774\uc800\uac00 \uc791\uc5c5\uc744 \uc870\uc728\ud569\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"examples/simple-chatbot":{"id":"examples/simple-chatbot","title":"\uac04\ub2e8\ud55c \ucc57\ubd07 \ub9cc\ub4e4\uae30","description":"LangGraph\ub85c \ub300\ud654 \uae30\ub85d\uc744 \uc720\uc9c0\ud558\ub294 \uae30\ubcf8 \ucc57\ubd07\uc744 \ub9cc\ub4e4\uc5b4\ubd05\ub2c8\ub2e4. \uc774 \uc608\uc81c\uc5d0\uc11c\ub294 State \uad00\ub9ac, \ub178\ub4dc \uc791\uc131, \uccb4\ud06c\ud3ec\uc778\ud305\uc758 \uae30\ucd08\ub97c \ubc30\uc6c1\ub2c8\ub2e4.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"LangGraph \uc18c\uac1c","description":"LangGraph\ub294 LLM(\ub300\uaddc\ubaa8 \uc5b8\uc5b4 \ubaa8\ub378)\uc744 \uc0ac\uc6a9\ud55c \uc0c1\ud0dc \uae30\ubc18 \ub2e4\uc911 \uc5d0\uc774\uc804\ud2b8 \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \uad6c\ucd95\ud558\uae30 \uc704\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4. LangChain \ud300\uc5d0\uc11c \uac1c\ubc1c\ud588\uc73c\uba70, \ubcf5\uc7a1\ud55c AI \uc6cc\ud06c\ud50c\ub85c\uc6b0\ub97c \uadf8\ub798\ud504 \ud615\ud0dc\ub85c \ud45c\ud604\ud558\uace0 \uc2e4\ud589\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","sidebar":"tutorialSidebar"}}}}')}}]);